!function(){"use strict";$(document).ready(function(){var u=jQuery.Event("kerberosAttempt");if($(document).trigger(u),!u.isDefaultPrevented())return $.ajax(portal+"authkrb",{dataType:"json",success:function(e){if(u=jQuery.Event("kerberosSuccess"),$(document).trigger(u,[e]),!u.isDefaultPrevented())return e.ajax_auth_token&&$("#lformKerberos").find('input[name="ajax_auth_token"]').attr("value",e.ajax_auth_token),$("#lformKerberos").submit()},error:function(e,r,t){if(u=jQuery.Event("kerberosFailure"),$(document).trigger(u,[e,r,t]),!u.isDefaultPrevented())return $("#lformKerberos").submit()}})})}();